        std::fs::create_dir_all(&private_character_path).expect("create <WTF-character> WTF path");

        let _guard = EnvVarGuard::set("WOW_SIM_WTF_CHARACTER", "<WTF-character>");
        let (_account, _realm, character) = default_wtf_identity(temp.path());

